import{demoData}from'./analytics.js';
import{analyzeDataset}from'./analytics/pipeline.js';
import{uploaderHTML}from'./uploader.js';
import{googleTemplateCopyURL}from'./site-config.js';
import {FIELDS} from './templates.js';
import {analyticsCoverage} from './analytics/engagement.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'Not enough data':Number(n).toLocaleString('en-US',{maximumFractionDigits:1});
export function coverageHTML(rows){const items=analyticsCoverage(rows);return `<div class="coverage"><h2>What ClubPulse can analyze</h2><p class="footnote">Ready means usable data is present. Trends and comparisons still need repeated meetings.</p><ul class="coverage-list">${items.filter(x=>x.label!=='True cohort retention').map(x=>`<li><div><strong>${esc(x.label==='Attendance trends'&&rows.length<6?'Attendance summary':x.label)}</strong>${!x.available?`<small>Add ${esc(x.field)} to unlock.</small>`:''}</div><span>${x.available?'Ready':'Not available'}</span></li>`).join('')}</ul><details><summary>Data completeness and analysis limits</summary>${items.map(x=>`<p>${esc(x.label)}: ${x.count} of ${x.total} meetings have usable data.</p>`).join('')}<p>Ready means the fields are present. Reliable trends and comparisons still need enough meetings. Anonymous IDs need follow-up meetings for cohort retention.</p></details></div>`}
export function homeHTML(hasRows,isDemo){
 const sample=analyzeDataset(demoData()),t=sample.outputs.calculate_attendance_trend,recent=sample.rows.slice(-8);
 const vals=recent.map(r=>r.attendance),max=Math.max(...vals),min=Math.min(...vals),points=vals.map((v,i)=>(12+i*40)+','+(95-(v-min)/(max-min||1)*65)).join(' ');
 return `<section class="home-hero"><div class="hero-copy"><p class="overline">A little data. A better next meeting.</p><h1>Understand what<br>drives your club<span class="hero-period">.</span></h1><p class="hero-description">ClubPulse analyzes your meeting history to show what changed, explain what may be driving it, and help you plan your next meeting.</p><div class="hero-actions"><a class="button primary" href="#import">Analyze My Club →</a><a class="button" href="#demo">Explore Demo →</a></div><div class="home-path-copy"><p><strong>Your club:</strong> Upload meeting history for trends, explanations, and next steps.</p><p><strong>The demo:</strong> Explore a fictional club with declining attendance.</p></div><p class="hero-note">Start with date + attendance. No account needed.</p></div><aside class="product-preview" aria-label="Preview calculated from fictional demo data"><div class="preview-top"><span class="preview-label">CLUB SNAPSHOT</span><span class="sample-label">Fictional demo</span></div><div class="preview-measure"><div><span>Recent attendance</span><strong>${fmt(t.current)}<small> / meeting</small></strong></div><span class="trend-change">↓ ${fmt(Math.abs(t.percentChange))}%</span></div><svg class="preview-chart" viewBox="0 0 310 120" role="img" aria-label="Attendance across the last eight fictional meetings"><path d="M12 30H292 M12 65H292 M12 100H292" class="preview-grid"/><polyline points="${points}" class="preview-line"/>${vals.map((v,i)=>`<circle cx="${12+i*40}" cy="${95-(v-min)/(max-min||1)*65}" r="3" class="preview-point"/>`).join('')}</svg><div class="preview-caption"><span>Last 8 meetings</span><span>Most recent</span></div><div class="preview-finding"><span class="finding-dot" aria-hidden="true"></span><div><strong>Something changed.</strong><p>The last three meetings averaged ${fmt(t.current)} attendees, down from ${fmt(t.baseline)} in the previous three.</p></div></div><a href="#demo" class="preview-action">Explore what may be behind it <span aria-hidden="true">→</span></a></aside></section><ol class="workflow"><li><strong>Add your data</strong><span>A spreadsheet is all you need.</span></li><li><strong>See what changed</strong><span>Find the signals that matter.</span></li><li><strong>Understand why</strong><span>Ask questions. Explore evidence.</span></li><li><strong>Plan your next meeting</strong><span>Choose what to try next.</span></li></ol>${hasRows?`<p class="home-resume"><a class="text-link" href="#overview">Continue with your ${isDemo?'demo':'current data'} →</a></p>`:''}<p class="home-privacy">Made for student leaders. Your meeting data stays in this browser tab.</p>`;
}


export function demoIntroHTML(snapshot){return `<section class="demo-intro"><p class="overline">See ClubPulse in action</p><h1>Attendance started falling.</h1><p class="demo-case">We’ll use <strong>${snapshot.rows.length} fictional meetings</strong> to understand what changed, what may be driving it, and what the club should try next.</p><p class="demo-dataset">Sample Club · Fictional data</p><div class="demo-intro-actions"><button class="button primary" id="start-demo-analysis">Start with the trend ↓</button><button class="text-link" id="skip-demo">Skip to Full Demo</button></div></section>`;}
export function sheetsHTML(templateURL){const url=googleTemplateCopyURL(templateURL);return `<div class="page-heading"><div><h1>Use Google Sheets with ClubPulse</h1><p>Keep your meeting history in one spreadsheet and add a new row after each meeting.</p></div></div><div class="sheets-steps"><section><span class="step-number">1</span><div><h2>${url?'Make your copy':'Get the template'}</h2><p>Start with the ClubPulse template. The columns, formatting and three fictional examples are already set up.</p>${url?`<a class="button primary" href="${url}" target="_blank" rel="noopener noreferrer">Make a Copy in Google Sheets →</a>`:'<button class="button" disabled>Make a Copy in Google Sheets</button><p class="unavailable-note">The Google copy template is being prepared. You can start now: download the formatted workbook and import it into Google Sheets.</p><a class="button primary" href="templates/clubpulse-template.xlsx" download>Download Excel template</a><details><summary>Use this workbook in Google Sheets</summary><p>Open a blank Google Sheet. Choose File → Import → Upload and select the workbook. No columns need to be recreated.</p><a href="https://sheets.google.com" target="_blank" rel="noopener noreferrer">Open Google Sheets ↗</a></details>'}</div></section><section><span class="step-number">2</span><div><h2>Add your meetings</h2><p>Replace the examples, then add one row after each meeting. Date and Attendance are all you need to start.</p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Meeting name</th><th>Attendance</th></tr></thead><tbody><tr><td>Sep 3</td><td>NBA Player Debate</td><td>28</td></tr><tr><td>Sep 10</td><td>Sports Analytics Intro</td><td>24</td></tr><tr><td>Sep 17</td><td>Prediction Challenge</td><td>35</td></tr></tbody></table></div><p class="footnote">Fictional examples. Keep your own copy private or share it with your officers.</p></div></section><section><span class="step-number">3</span><div><h2>Bring it back to ClubPulse</h2><h3>Ready to analyze it?</h3><p>In Google Sheets, download your completed sheet as Excel or CSV, then upload it below.</p><p><strong>Google Sheets → File → Download → Microsoft Excel (.xlsx)</strong></p><section id="import-section" class="completed-sheet-upload">${uploaderHTML('Upload Your Completed Sheet')}</section><p class="footnote">ClubPulse currently analyzes spreadsheet files. Direct Google Sheets syncing is not enabled yet. Keep using the same Sheet and download the latest version whenever you want a new analysis.</p></div></section></div><details class="format-help"><summary>What extra information helps?</summary><div class="field-guide">${FIELDS.map(f=>`<div><strong>${esc(f[1])}</strong><p>${esc(f[3])}</p></div>`).join('')}</div></details>`}

export function highlightsHTML(outputs){const t=outputs.calculate_attendance_trend,reach=outputs.analyze_social_reach,member=outputs.analyze_member_engagement;const cards=[{label:'Attendance',change:t.available?t.percentChange:null,unit:'%',meaning:t.available?`${fmt(t.current)} people per meeting, previously ${fmt(t.baseline)}.`:'Record at least six meetings to compare periods.'},{label:'Promotion reach',change:reach.trend?.percentChange,unit:'%',meaning:reach.trend?`${fmt(reach.trend.recent)} accounts reached, previously ${fmt(reach.trend.previous)}.`:'Add reach to the last six meetings to compare exposure.'},{label:'Returning attendees',change:member.trend?.percentagePoints,unit:' pts',meaning:member.trend?`${fmt(member.trend.recent*100)}% of attendance, previously ${fmt(member.trend.previous*100)}%.`:'Add consistent member counts or anonymous IDs to compare returning turnout.'}];return `<section class="card notice-story" id="notice-story"><h2>What should I notice?</h2><p>Last three meetings compared with the previous three.</p><div class="notice-grid">${cards.map(c=>`<article class="${c.change==null?'missing-finding':'measured-finding'}"><h2>${c.label}</h2><strong>${c.change==null?'More data needed':`${c.change<0?'↓':c.change>0?'↑':'→'} ${fmt(Math.abs(c.change))}${c.unit}`}</strong><p>${c.meaning}</p></article>`).join('')}</div><p class="footnote">These are signals to investigate. They do not prove why attendance changed. Returning share is not cohort retention.</p><p><strong>Want to know why?</strong></p><button class="button primary" id="investigate-change">Ask ClubPulse why →</button></section>`}
export function installTour(root){let seen=false;try{seen=localStorage.getItem('clubpulse-tour-seen')==='yes'}catch{}const panel=document.createElement('section');panel.className='tour-panel';panel.innerHTML='<button class="text-link" id="launch-tour">Take a quick tour</button><div id="tour-body" hidden></div>';root.prepend(panel);const steps=[['Add your meeting history','Start in Your Data with Google Sheets, Excel, CSV or manual entry. Only date and attendance are required.','#notice-story'],['See the trend and meetings','The graph shows every meeting. The comparison below uses the last three and previous three; the table lets you inspect the records.','#attendance-evidence'],['Ask why','ClubPulse selects analytical tools and explains the calculated evidence.','.ask-disclosure'],['Plan your next meeting','Use your history to estimate turnout and choose what to try.','.next-idea']];let index=0;const body=panel.querySelector('#tour-body');const finish=()=>{body.hidden=true;try{localStorage.setItem('clubpulse-tour-seen','yes')}catch{}root.querySelectorAll('.tour-highlight').forEach(e=>e.classList.remove('tour-highlight'))};const show=()=>{body.hidden=false;const [title,text,selector]=steps[index];body.innerHTML=`<p><strong>${index+1} / ${steps.length} · ${title}</strong></p><p>${text}</p><button class="button small" id="tour-next">${index===steps.length-1?'Finish':'Next'}</button> <button class="text-link" id="tour-skip">Skip tour</button>${index===steps.length-1?'<a class="text-link" href="#predict">Try a forecast →</a>':''}`;root.querySelectorAll('.tour-highlight').forEach(e=>e.classList.remove('tour-highlight'));const target=root.querySelector(selector);if(target){const d=target.closest('details');if(d)d.open=true;target.classList.add('tour-highlight');target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}body.querySelector('#tour-next').onclick=()=>{if(++index===steps.length)finish();else show()};body.querySelector('#tour-skip').onclick=finish};panel.querySelector('#launch-tour').onclick=()=>{index=0;show()};if(!seen){body.hidden=false;body.innerHTML='<p>New to ClubPulse? Take a short, optional tour.</p><button class="button small" id="tour-start">Show me around</button> <button class="text-link" id="tour-skip">Skip tour</button>';body.querySelector('#tour-start').onclick=show;body.querySelector('#tour-skip').onclick=finish}}
